// Travel power index — record JAH-GGNS-TRAVELADAPTER-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"countries": 150, "usb_w": 65, "price_usd": 40};
var value = (m.countries*m.usb_w/m.price_usd);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GGNS-TRAVELADAPTER-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GGNS-TRAVELADAPTER-000001|' + value.toFixed(2) + ' travel index');

